Use a max-heap for the lower half and a min-heap for the upper half. Keep the lower heap equal in size to the upper heap or one element larger, with every lower value no greater than every upper value. Empty input returns []; duplicates and negative integers are handled normally.

```javascript
function solve(nums) {
  class Heap {
    constructor(before) {
      this.data = [];
      this.before = before;
    }

    get size() {
      return this.data.length;
    }

    peek() {
      return this.data[0];
    }

    push(value) {
      const a = this.data;
      a.push(value);
      let i = a.length - 1;
      while (i > 0) {
        const parent = Math.floor((i - 1) / 2);
        if (!this.before(a[i], a[parent])) break;
        [a[i], a[parent]] = [a[parent], a[i]];
        i = parent;
      }
    }

    pop() {
      const a = this.data;
      if (a.length === 0) return undefined;
      const root = a[0];
      const last = a.pop();
      if (a.length > 0) {
        a[0] = last;
        let i = 0;
        while (true) {
          const left = 2 * i + 1;
          const right = left + 1;
          let best = i;
          if (left < a.length && this.before(a[left], a[best])) {
            best = left;
          }
          if (right < a.length && this.before(a[right], a[best])) {
            best = right;
          }
          if (best === i) break;
          [a[i], a[best]] = [a[best], a[i]];
          i = best;
        }
      }
      return root;
    }
  }

  const lower = new Heap((a, b) => a > b);
  const upper = new Heap((a, b) => a < b);
  const medians = [];

  for (const num of nums) {
    if (lower.size === 0 || num <= lower.peek()) {
      lower.push(num);
    } else {
      upper.push(num);
    }

    if (lower.size > upper.size + 1) {
      upper.push(lower.pop());
    } else if (upper.size > lower.size) {
      lower.push(upper.pop());
    }

    medians.push(
      lower.size === upper.size
        ? lower.peek() / 2 + upper.peek() / 2
        : lower.peek()
    );
  }

  return medians;
}
```

Time: O(n log n) overall; space: O(n), including the returned array. Uses JavaScript Number arithmetic.

